#!/usr/bin/env node
// screenshot.mjs — capture a screenshot from an obscura CDP server via Playwright.
//
// Obscura is the headless browser backend (Rust, CDP-compatible). This script does
// NOT launch a browser — it connects to a running `obscura serve` instance over CDP
// and uses Playwright purely as a thin automation client (no bundled Chromium needed).
//
// Prereq: `obscura serve --port 9222` is already running.
// Run:
//   node screenshot.mjs https://example.com out.png
//   node screenshot.mjs https://example.com out.png --full-page
//   node screenshot.mjs https://example.com out.png --viewport 1280,2000 --wait-until networkidle0
//   OBS CURA_CDP=ws://127.0.0.1:9222 node screenshot.mjs https://example.com out.png
//
// Requires `playwright-core` (or `playwright`) on the Node resolution path. To run
// without a local install:
//   npx --package=playwright-core -- node screenshot.mjs https://example.com out.png

const args = process.argv.slice(2);
const positional = args.filter((a) => !a.startsWith("--"));
const flags = new Set(args.filter((a) => a.startsWith("--")));
const url = positional[0] ?? process.env.URL ?? "https://example.com";
const out = positional[1] ?? process.env.SCREENSHOT_OUT ?? "screenshot.png";
const cdp = process.env.OBSCURA_CDP ?? process.env.CDP_ENDPOINT ?? "ws://127.0.0.1:9222";

function flagValue(name) {
  const i = args.indexOf(`--${name}`);
  return i >= 0 ? args[i + 1] : undefined;
}

const viewport = flagValue("viewport"); // e.g. "1280,2000"
const waitUntil = flagValue("wait-until") ?? "load"; // load | domcontentloaded | networkidle0
const selector = flagValue("selector"); // wait for a CSS selector before shooting
const timeout = Number(flagValue("timeout") ?? 30) * 1000;
const fullPage = flags.has("--full-page");

async function loadDriver() {
  // Prefer playwright-core (no browser download); fall back to playwright.
  for (const mod of ["playwright-core", "playwright"]) {
    try {
      return await import(mod);
    } catch {
      /* try next */
    }
  }
  throw new Error(
    "Neither 'playwright-core' nor 'playwright' is importable. Install with: npm i playwright-core"
  );
}

const { chromium } = await loadDriver();

let browser;
try {
  browser = await chromium.connectOverCDP({ endpointURL: cdp });
} } catch (err) {
  console.error(`✗ Could not connect to obscura CDP at ${cdp}`);
  console.error(`  Is "obscura serve --port ${new URL(cdp).port || 9222}" running?`);
  console.error(`  ${err.message}`);
  process.exit(1);
}

try {
  // Reuse the default browser context obscura exposes over CDP.
  const context = browser.contexts()[0] ?? (await browser.newContext());
  const page = await context.newPage();

  if (viewport) {
    const [w, h] = viewport.split(",").map(Number);
    if (w && h) await page.setViewportSize({ width: w, height: h });
  }

  await page.goto(url, { waitUntil, timeout });
  if (selector) await page.waitForSelector(selector, { timeout });

  await page.screenshot({ path: out, fullPage });
  const title = await page.title().catch(() => "");
  console.log(`✓ Screenshot saved → ${out}`);
  console.log(`  url:   ${url}`);
  if (title) console.log(`  title: ${title}`);
  await page.close().catch(() => {});
} finally {
  // disconnect (don't close the obscura server)
  await browser.close().catch(() => {});
}

