const { existsSync, readdirSync } = await import("node:fs");
const { join } = await import("node:path");
const { homedir } = await import("node:os");

// Candidate roots where playwright-core / playwright may already be installed,
// even if not resolvable from this script's directory (e.g. the npx cache).
function candidateRoots() {
  const roots = [];
  if (process.env.NODE_PATH) roots.push(...process.env.NODE_PATH.split(":"));
  // Global npm install location
  try {
    const global = execSync("npm root -g").toString().trim();
    if (global) roots.push(global);
  } catch {}
  // npx cache (~/.npm/_npx/*/node_modules) — populates on `npx playwright` etc.
  const npxDir = join(homedir(), ".npm", "_npx");
  if (existsSync(npxDir)) {
    for (const hash of readdirSync(npxDir)) {
      roots.push(join(npxDir, hash, "node_modules"));
    }
  }
  // Explicit override
  if (process.env.PLAYWRIGHT_CORE) roots.push(process.env.PLAYWRIGHT_CORE);
  return roots;
}

async function loadDriver() {
  const { execSync } = await import("node:child_process");
  // 1) Try the normal bare-module resolution first (local install / NODE_PATH).
  for (const mod of ["playwright-core", "playwright"]) {
    try {
      return await import(mod);
    } catch {}
  }
  // 2) Search candidate roots and import the absolute directory path.
  for (const root of candidateRoots()) {
    for (const mod of ["playwright-core", "playwright"]) {
      const dir = join(root, mod);
      if (existsSync(join(dir, "package.json"))) {
        try {
          return await import(dir + "/index.js");
        } catch {
          try {
            return await import(dir);
          } catch {}
        }
      }
    }
  }
  throw new Error(
    "Neither 'playwright-core' nor 'playwright' is importable. Install one with: npm i -g playwright-core (then run with NODE_PATH=$(npm root -g)), or run this script via: npx --package=playwright-core -- node screenshot.mjs ..."
  );
}

